
"use client"; // Added to use usePathname hook

import type { Metadata } from 'next';
import { Geist, Geist_Mono } from 'next/font/google';
import './globals.css';
import { Toaster } from '@/components/ui/toaster';
import Header from '@/components/layout/header';
import Footer from '@/components/layout/footer';
import { cn } from '@/lib/utils';
import { ThemeProvider } from '@/context/theme-provider';
import ScrollToTopButton from '@/components/ui/scroll-to-top-button';
import { usePathname } from 'next/navigation'; // Imported usePathname

const geistSans = Geist({
  variable: '--font-geist-sans',
  subsets: ['latin'],
});

const geistMono = Geist_Mono({
  variable: '--font-geist-mono',
  subsets: ['latin'],
});

// Metadata should ideally be defined in a Server Component if RootLayout becomes client only.
// For now, keeping it here but be aware this might need adjustment for more complex scenarios.
// If you need dynamic metadata based on routes, you'd typically export 'generateMetadata' from page.tsx or layout.tsx (server components).
export const metadata: Metadata = {
  title: 'KASUPDA - Kaduna State Urban Planning and Development Authority',
  description: 'Official portal for KASUPDA, Kaduna State.',
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const pathname = usePathname();
  const isDashboardPage = pathname.startsWith('/dashboard');

  return (
    <html lang="en" suppressHydrationWarning>
      <body
        className={cn(
          geistSans.variable,
          geistMono.variable,
          'antialiased min-h-screen flex flex-col'
        )}
      >
        <ThemeProvider>
          {!isDashboardPage && <Header />}
          <main className={cn(
            "flex-grow",
            !isDashboardPage && "container mx-auto px-4 py-8" // Apply container and padding only if not dashboard
          )}>
            {children}
          </main>
          {!isDashboardPage && <Footer />}
          <Toaster />
          <ScrollToTopButton />
        </ThemeProvider>
      </body>
    </html>
  );
}
